const html = $input.first().json.data ?? "";
const clean = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;|&#160;/g, " ")
  .replace(/\s+/g, " ")
  .trim();
const offers = [];
const seen = new Set();
const pct = /([A-Z][A-Za-z0-9'&.\- ]{3,60}?)\s*(?:[-\u2013\u2014:|]\s*)?(?:up\s+to\s+)?(\d{1,2})\s*%\s*(off|discount)?/gi;
let m;
while ((m = pct.exec(clean)) !== null && offers.length < 15) {
  const merchant = m[1].trim().split(/\s{2,}/)[0].slice(0, 32);
  const key = merchant.toLowerCase();
  if (seen.has(key) || merchant.length < 3) continue;
  seen.add(key);
  offers.push({ merchant, value: Number(m[2]), kind: "percent" });
}
const installments = /0%\s*(?:installments?|for)\s*(\d{1,2})\s*months?/gi;
while ((m = installments.exec(clean)) !== null && offers.length < 20) {
  offers.push({ merchant: "Jarir installments", value: Number(m[1]), kind: "installments" });
}
return [{ json: { offers, pageChars: clean.length } }];

const TARGET = "https://www.jarir.com/sa-en/offers";
const { offers, pageChars } = $input.first().json;
const now = new Date();
const norm = offers.map((o, i) => ({
  id: "jarir-" + now.getTime().toString(36) + "-" + i,
  merchant: "Jarir",
  headline: o.kind === "installments"
    ? "0% installments for " + o.value + " months \u2014 " + o.merchant
    : o.merchant + " \u2014 " + o.value + "% off with linked bank cards",
  discountLabel: o.kind === "installments" ? "0% \u00d7" + o.value : "\u2212" + o.value + "%",
  value: o.value,
  kind: o.kind === "installments" ? "installments" : "percent",
  category: "electronics",
  bank: "Jarir",
  card: "All bank cards",
  image: "",
  cards: ["All bank cards"],
  link: TARGET,
  expiresAt: null,
  terms: ["Parsed by the onlydeals-jarir n8n workflow \u2014 open the link for full terms."]
}));
const payload = {
  version: "offer.v1",
  generatedAt: now.toISOString(),
  generator: "n8n:onlydeals-jarir",
  sources: [{
    id: "jarir",
    name: "Jarir",
    status: norm.length ? "live" : "error",
    count: norm.length,
    note: norm.length + " offers \u00b7 html regex \u00b7 " + pageChars + " chars parsed",
    at: now.getTime()
  }],
  offers: norm
};
return [{ json: { payload, count: norm.length } }];

const p = $('Build offer.v1 payload').first().json.payload;
const s = (p.sources && p.sources[0]) || {};
return [{ json: { timestamp: p.generatedAt, source: s.id || '', offers: s.count || 0, status: s.status || '', generator: p.generator } }];
